  /// `/IstiN/fa_widgets/main/widgets/fa-craft/icon.svg` →
  /// `widgets/fa-craft/icon.svg`.
  String relOf(String path) {
    final parts = path.split('/')..removeAt(0); // leading empty segment
    if (parts.length <= 3) return path;
